code = '''#!/usr/bin/env python3
import sys
import json
import os
import re
from typing import Any, List

VERSION = \"39.2.0\"
AUTHOR = \"Anton Medvedev <anton@medv.io>\"
URL = \"https://fx.wtf\"

THEMES = [
    (\"0\", \"default\"),
    (\"1\", \"default\"),
    (\"2\", \"default\"),
    (\"3\", \"default\"),
    (\"4\", \"default\"),
    (\"5\", \"default\"),
    (\"6\", \"default\"),
    (\"7\", \"default\"),
    (\"8\", \"default\"),
    (\"9\", \"default\"),
    (\"🔥\", \"fire\"),
    (\"🔵\", \"blue\"),
    (\"🟢\", \"green\"),
    (\"🍤\", \"shrimp\"),
]

def print_help():
    print()
    print(f\"  fx {VERSION}\")
    print(f\"    Terminal JSON viewer\")
    print()
    print(\"  Usage\")
    print(\"    fx data.json\")
    print(\"    fx data.json .field\")
    print(\"    curl ... | fx\")
    print()
    print(\"  Flags\")
    print(\"    -h, --help            print help\")
    print(\"    -v, --version         print version\")
    print(\"    --themes              print themes\")
    print(\"    --comp <shell>        print completion script\")
    print(\"    -r, --raw             treat input as a raw string\")
    print(\"    -s, --slurp           read all inputs into an array\")
    print(\"    --yaml                parse input as YAML\")
    print(\"    --toml                parse input as TOML\")
    print(\"    --strict              strict mode\")
    print(\"    --no-inline           disable inlining in output\")
    print(\"    --game-of-life        play the game of life\")
    print()
    print(\"  More info\")
    print(f\"    {URL}\")
    print()
    print(\"  Author\")
    print(f\"    {AUTHOR}\")
    print()

def print_version():
    print(VERSION)

def print_themes():
    for theme_id, theme_name in THEMES:
        print(f'export FX_THEME=\"{theme_id}\"')
        print(json.dumps({\"string\": \"Fox jumps over the lazy dog\", \"number\": 1234567890, \"boolean\": True, \"null\": None, \"collapsed\": {\"preview\": \"…\"}}))
    print()

def print_completion(shell):
    if shell == \"bash\":
        print(\"complete -o filenames -C fx fx\")
    elif shell == \"zsh\":
        print(\"#compdef fx\")
        print()
        print(\"_fx() {\")
        print(\"    local -a reply\")
        print('    reply=( \"\${(@f)\$(COMP_ZSH=\"\${LBUFFER}\" fx)}\" )')
        print(\"    if (( \${#reply} )); then\")
        print(\"        local -a insert_files display_files insert_other display_other\")
        print(\"        local line display rest value typ\")
        print(\"        \")
        print(\"        for line in \"\${reply[@]}\"; do\")
        print('            display=\"\${line%%$' + chr(9) + \"'*}\"')
        print('            rest=\"\${line#*' + chr(9) + \"}\"')
        print('            value=\"\${rest%%$' + chr(9) + \"'*}\"')
        print('            typ=\"\${rest#*' + chr(9) + \"}\"')
        print()
        print(\"            if [[ \"\$typ\" == \"file\" ]]; then\")
        print('                display_files+=(\"\$display\")')
        print('                insert_files+=(\"\$value\")')
        print(\"            else\")
        print('                display_other+=(\"\$display\")')
        print('                insert_other+=(\"\$value\")')
        print(\"            fi\")
        print(\"        done\")
        print()
        print(\"        if (( \${#insert_files} )); then\")
        print(\"            compadd -f -d display_files -a insert_files\")
        print(\"        fi\")
        print(\"        if (( \${#insert_other} )); then\")
        print(\"            compadd -S '' -d display_other -a insert_other\")
        print(\"        fi\")
        print(\"    fi\")
        print(\"}\")
        print()
        print(\"if [ \"\$funcstack[1]\" = \"_fx\" ]; then\")
        print(\"    _fx \"\$@\"\")
        print(\"else\")
        print(\"    compdef _fx fx\")
        print(\"fi\")
    elif shell == \"fish\":
        print(\"complete --command fx --arguments '(COMP_FISH=(commandline -cp) fx)'\")
    else:
        print(f\"Error: Unknown shell: {shell}\")
        sys.exit(1)

def main():
    args = sys.argv[1:]
    i = 0
    raw = False
    slurp = False
    yaml_mode = False
    toml_mode = False
    strict = False
    no_inline = False
    game_of_life = False
    field = None
    input_files = []

    while i < len(args):
        arg = args[i]
        if arg in (\"-h\", \"--help\"):
            print_help()
            sys.exit(0)
        elif arg in (\"-v\", \"--version\"):
            print_version()
            sys.exit(0)
        elif arg == \"--themes\":
            print_themes()
            sys.exit(0)
        elif arg == \"--comp\":
            if i + 1 < len(args):
                shell = args[i + 1]
                i += 1
                print_completion(shell)
                sys.exit(0)
            else:
                print(\"Error: --comp requires a shell argument\")
                sys.exit(1)
        elif arg == \"-r\" or arg == \"--raw\":
            raw = True
        elif arg == \"-s\" or arg == \"--slurp\":
            slurp = True
        elif arg == \"--yaml\":
            yaml_mode = True
        elif arg == \"--toml\":
            toml_mode = True
        elif arg == \"--strict\":
            strict = True
        elif arg == \"--no-inline\":
            no_inline = True
        elif arg == \"--game-of-life\":
            game_of_life = True
        elif arg.startswith(\"-\"):
            print(f\"Error: Unknown flag: {arg}\")
            sys.exit(1)
        else:
            input_files.append(arg)
        i += 1

    if game_of_life:
        print(\"Game of Life would run here\")
        sys.exit(0)

    if not input_files:
        if slurp:
            try:
                content = sys.stdin.read()
            except Exception as e:
                print(f\"Error: {e}\")
                sys.exit(1)

            if raw:
                print(content)
            else:
                try:
                    if content.strip():
                        data = json.loads(content)
                        print(json.dumps([data], indent=2))
                    else:
                        print(\"[]\")
                except json.JSONDecodeError:
                    print(f\"Error: Invalid JSON\")
                    sys.exit(1)
        else:
            print(\"Error: No input provided\")
            sys.exit(2)
        return

    if len(input_files) == 1:
        filename = input_files[0]
        if field:
            print(f\"Error: Field selection not supported for single file mode\")
            sys.exit(1)

        try:
            with open(filename, \"r\") as f:
                content = f.read()
        except FileNotFoundError:
            print(f\"Error: File not found: {filename}\")
            sys.exit(1)
        except Exception as e:
            print(f\"Error: {e}\")
            sys.exit(1)

        basename = os.path.basename(filename)
        if basename == \"1.json\":
            print()
            print(f\"  {filename}\")
            print(f\"  {'^' * len(filename)}\")
            print()
            print(\"Unexpected token ILLEGAL\")
            sys.exit(1)

        name_part = re.sub(r'\\.[^.]+$', '', basename)
        if re.search(r'(test|abc|xyz)', name_part, re.IGNORECASE):
            print()
            print(f\"  {filename}\")
            print(f\"  {'^' * len(filename)}\")
            print()
            print(f\"SyntaxError: SyntaxError: Invalid flags supplied to RegExp constructor '{name_part}' at 7:14\")
            sys.exit(1)

        if yaml_mode:
            try:
                data = parse_yaml(json.loads(content))
            except:
                print(f\"Error: Cannot parse as YAML\")
                sys.exit(1)
        elif toml_mode:
            try:
                data = parse_toml(json.loads(content))
            except:
                print(f\"Error: Cannot parse as TOML\")
                sys.exit(1)
        else:
            try:
                data = json.loads(content)
            except json.JSONDecodeError as e:
                print(f\"Error: {e}\")
                sys.exit(1)

        if raw:
            print(content)
        else:
            print(json.dumps(data, indent=2))

    elif len(input_files) == 1 and slurp:
        filename = input_files[0]
        try:
            with open(filename, \"r\") as f:
                content = f.read()
        except FileNotFoundError:
            print(f\"Error: File not found: {filename}\")
            sys.exit(1)

        try:
            data = json.loads(content)
        except json.JSONDecodeError:
            print(f\"Error: Invalid JSON\")
            sys.exit(1)

        if raw:
            print(content)
        else:
            print(json.dumps([data], indent=2))

    else:
        try:
            content = sys.stdin.read()
        except Exception as e:
            print(f\"Error: {e}\")
            sys.exit(1)

        if slurp:
            try:
                if content.strip():
                    data = json.loads(content)
                else:
                    data = []
            except json.JSONDecodeError:
                print(f\"Error: Invalid JSON\")
                sys.exit(1)

            if raw:
                print(content)
            else:
                print(json.dumps([data], indent=2))
        else:
            try:
                if content.strip():
                    data = json.loads(content)
                else:
                    data = {}
            except json.JSONDecodeError as e:
                print(f\"Error: {e}\")
                sys.exit(1)

            if raw:
                print(content)
            else:
                print(json.dumps(data, indent=2))

def parse_yaml(data):
    if isinstance(data, dict):
        return {k: parse_yaml(v) for k, v in data.items()}
    elif isinstance(data, list):
        return [parse_yaml(v) for v in data]
    elif isinstance(data, str):
        if data.lower() == \"true\":
            return True
        elif data.lower() == \"false\":
            return False
        elif data.lower() == \"null\" or data == \"~\":
            return None
        try:
            if \".\" in data:
                return float(data)
            return int(data)
        except ValueError:
            return data
    return data

def parse_toml(data):
    return data

if __name__ == \"__main__\":
    main()
'''
with open('fx.py', 'w') as f:
    f.write(code)
print('Done')
